begin;
create extension if not exists pgtap with schema extensions;
select plan(8);
insert into auth.users(id,email) values ('40000000-0000-0000-0000-000000000001','calendar-customer@example.test'),('40000000-0000-0000-0000-000000000002','calendar-admin@example.test');
update public.profiles set role='admin' where id='40000000-0000-0000-0000-000000000002';
insert into public.professionals(id,display_name) values('40000000-0000-0000-0000-000000000010','Profesional calendario');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','40000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.admin_create_working_hours('40000000-0000-0000-0000-000000000010'::uuid,1::smallint,'09:00'::time,'10:00'::time,current_date,null::date)$$,'42501',null,'Un cliente no puede crear horarios mediante RPC');
select set_config('request.jwt.claim.sub','40000000-0000-0000-0000-000000000002',true);
create temporary table c(id uuid, break_id uuid, block_id uuid) on commit drop;
select lives_ok($$insert into c(id) select public.admin_create_working_hours('40000000-0000-0000-0000-000000000010'::uuid,1::smallint,'09:00'::time,'10:00'::time,current_date,null::date)$$,'Admin crea horario por RPC');
select lives_ok($$select public.admin_update_working_hours((select id from c),'09:00'::time,'11:00'::time,current_date,null::date,true,null)$$,'Admin actualiza horario por RPC');
select lives_ok($$update c set break_id=public.admin_create_recurring_break('40000000-0000-0000-0000-000000000010'::uuid,1::smallint,'10:00'::time,'10:15'::time,current_date,null::date)$$,'Admin crea descanso por RPC');
select lives_ok($$select public.admin_update_recurring_break((select break_id from c),false,clock_timestamp())$$,'Admin desactiva descanso por RPC');
select lives_ok($$update c set block_id=public.admin_create_calendar_block('professional','40000000-0000-0000-0000-000000000010'::uuid,clock_timestamp()+interval '10 days',clock_timestamp()+interval '10 days 1 hour',false,'Prueba local')$$,'Admin crea bloqueo profesional por RPC');
select lives_ok($$select public.admin_update_calendar_block((select block_id from c),'professional','40000000-0000-0000-0000-000000000010'::uuid,clock_timestamp()+interval '10 days',clock_timestamp()+interval '10 days 2 hours',false,true,null,'Actualizado')$$,'Admin actualiza bloqueo por RPC');
select ok(not has_table_privilege('authenticated','public.calendar_blocks','INSERT') and not has_table_privilege('authenticated','public.professional_working_hours','UPDATE') and not has_table_privilege('authenticated','public.professional_recurring_breaks','DELETE'),'El DML directo permanece revocado para authenticated');
select * from finish(); rollback;
